import torch
import torch.nn.functional as F

def run(input, weight, padding, stride, dilation, groups, benchmark, deterministic, allow_tf32):
    ndim = input.ndim - 2
    if ndim == 1:
        return F.conv1d(input, weight, bias=None, stride=stride, padding=padding, dilation=dilation, groups=groups)
    elif ndim == 2:
        return F.conv2d(input, weight, bias=None, stride=stride, padding=padding, dilation=dilation, groups=groups)
    elif ndim == 3:
        return F.conv3d(input, weight, bias=None, stride=stride, padding=padding, dilation=dilation, groups=groups)
    else:
        raise ValueError(f'unsupported ndim {ndim}')
